// Turns the values in Settings into the inputs of both job actors and refuses values they cannot run.
const s = $('Settings').first().json;
const keyword = String(s.keyword ?? '').trim();
const location = String(s.location ?? '').trim();
if (!keyword && !location) {
  throw new Error('Settings: give a keyword, a location or both.');
}
if (/^\d{4,5}$/.test(location)) {
  throw new Error('Settings: XING Jobs does not understand postcodes. Write the city name, e.g. Berlin.');
}
const common = { includeDetails: true, maxItems: Math.max(1, Math.round(Number(s.maxJobsPerSource) || 20)) };
if (keyword) common.keyword = keyword;
if (location) common.location = location;
if (s.publishedSince !== '' && s.publishedSince !== null && s.publishedSince !== undefined) {
  const days = Math.round(Number(s.publishedSince));
  if (!Number.isNaN(days)) common.publishedSince = Math.min(100, Math.max(0, days));
}
// Temp agencies are left out on the Arbeitsagentur side; delete excludeTemporaryEmployment to keep them.
const arbeitsagentur = { ...common, excludeTemporaryEmployment: true };
if (location) arbeitsagentur.radiusKm = Math.min(200, Math.max(0, Math.round(Number(s.radiusKm) || 25)));
// XING always searches 20 km around the place and refuses excludeTemporaryEmployment, so neither is sent.
const xing = { ...common };
return [{ json: { arbeitsagentur, xing } }];

// Both job runs must have succeeded. Their datasets go to the merge step in this order:
// rows from the Arbeitsagentur rank first, so their fields are the base of a merged row.
const runs = [
  ['Run Arbeitsagentur Jobs', $('Run Arbeitsagentur Jobs').first().json],
  ['Run XING Jobs', $('Run XING Jobs').first().json],
];
const datasets = [];
for (const [node, run] of runs) {
  const message = run.statusMessage || '';
  if (run.status !== 'SUCCEEDED' || /^Rejected/i.test(message)) {
    throw new Error(`${node}: run ${run.id} ended with status ${run.status}: ${message}`);
  }
  if (!run.defaultDatasetId) {
    throw new Error(`${node}: run ${run.id} has no dataset.`);
  }
  datasets.push(run.defaultDatasetId);
}
return [{ json: { datasets } }];

// Stops here when the run did not succeed or the actor rejected its input, with Apify's own status message.
const run = $input.first().json;
const message = run.statusMessage || '';
if (run.status !== 'SUCCEEDED' || /^Rejected/i.test(message)) {
  throw new Error(`Run ${run.id} ended with status ${run.status}: ${message}`);
}
if (!run.defaultDatasetId) {
  throw new Error(`Run ${run.id} has no dataset.`);
}
return [{ json: { runId: run.id, datasetId: run.defaultDatasetId, statusMessage: message } }];

// Job ads name the employer, not its website. Candidates, in this order: the domains of e-mail addresses in the
// ad text, then the domain of the application link. Free mail, job boards and applicant tracking systems are
// left out. Only the domain is kept, never the e-mail address itself.
const NOT_EMPLOYER = new Set(["gmail.com", "googlemail.com", "web.de", "gmx.de", "gmx.net", "gmx.at", "gmx.ch", "t-online.de", "outlook.com", "outlook.de", "hotmail.com", "hotmail.de", "live.com", "live.de", "msn.com", "yahoo.com", "yahoo.de", "icloud.com", "me.com", "mail.de", "freenet.de", "posteo.de", "arcor.de", "aol.com", "aol.de", "online.de", "vodafone.de", "kabelmail.de", "email.de", "proton.me", "protonmail.com", "1und1.de", "mailbox.org", "bluewin.ch", "arbeitsagentur.de", "bundesagentur.de", "jobboerse.de", "stepstone.de", "stepstone.at", "stepstone.com", "indeed.com", "indeed.de", "xing.com", "linkedin.com", "monster.de", "monster.com", "jobware.de", "stellenanzeigen.de", "kimeta.de", "jobs.de", "meinestadt.de", "heyjobs.co", "heyjobs.de", "bewerbung.jobs", "jobvector.de", "europersonal.com", "finest-jobs.com", "onapply.de", "persy.jobs", "joblocal.de", "yourfirm.de", "karriere.at", "jobs.ch", "jobscout24.ch", "jobup.ch", "stellenwerk.de", "stellenmarkt.de", "jobanzeiger.de", "jobninja.com", "jooble.org", "adzuna.de", "glassdoor.de", "glassdoor.com", "kununu.com", "softgarden.io", "softgarden.de", "personio.de", "personio.com", "join.com", "recruitee.com", "greenhouse.io", "lever.co", "myworkdayjobs.com", "workday.com", "successfactors.com", "successfactors.eu", "sapsf.com", "sapsf.eu", "smartrecruiters.com", "dvinci.de", "dvinci-hr.com", "dvinci-easy.com", "rexx-systems.com", "rexx-recruitment.com", "concludis.de", "prescreen.io", "onlyfy.jobs", "umantis.com", "haufe.com", "hrworks.de", "talents-connect.com", "bite.de", "bite-recruiting.de", "coveto.de", "mhm-hr.com", "jobbase.io", "jobposting.io", "jobs2web.com", "icims.com", "taleo.net", "google.com", "google.de", "goo.gl", "bit.ly", "facebook.com", "instagram.com", "youtube.com", "tiktok.com", "wa.me", "whatsapp.com", "apple.com", "microsoft.com", "zoom.us", "calendly.com"]);
const SECOND_LEVEL = new Set(['co.at', 'or.at', 'ac.at', 'gv.at', 'co.uk', 'org.uk', 'ac.uk', 'com.au']);
const FILE_ENDINGS = new Set(['png', 'jpg', 'jpeg', 'gif', 'svg', 'webp', 'pdf', 'doc', 'docx']);
const MAIL = /[\w.+-]{1,64}@([\w-]{1,63}(?:\.[\w-]{1,63})+)/g;

function registrable(host) {
  const labels = String(host).toLowerCase().replace(/^www\./, '').split('.').filter(Boolean);
  const tld = labels[labels.length - 1] || '';
  if (labels.length < 2 || !/^[a-z]{2,24}$/.test(tld) || FILE_ENDINGS.has(tld)) return null;
  if (labels.length >= 3 && SECOND_LEVEL.has(labels.slice(-2).join('.'))) return labels.slice(-3).join('.');
  return labels.slice(-2).join('.');
}
// The Code node sandbox has no URL class, so the host is read with a pattern.
function hostOf(url) {
  const match = /^[a-z][a-z0-9+.-]*:\/\/(?:[^\/?#@]*@)?([^\/?#:]+)/i.exec(String(url || ''));
  return match ? match[1] : null;
}

const rows = $input.all().map(item => item.json).filter(row => row && Object.keys(row).length > 0);
if (rows.length === 0) {
  throw new Error('No company rows: the job searches found no jobs for these settings.');
}
return rows.map(row => {
  const candidates = [];
  for (const match of String(row.description || '').matchAll(MAIL)) {
    candidates.push({ domain: registrable(match[1]), from: 'e-mail address in the ad' });
  }
  const link = hostOf(row.externalUrl);
  if (link) candidates.push({ domain: registrable(link), from: 'application link' });
  const pick = candidates.find(c => c.domain && !NOT_EMPLOYER.has(c.domain)) || null;
  const places = (Array.isArray(row.locations) ? row.locations : [])
    .map(l => [l && l.zip, l && l.city].filter(Boolean).join(' '))
    .filter(Boolean);
  return {
    json: {
      employer: row.company || row.companyLegalName || '',
      website: pick ? pick.domain : null,
      websiteFrom: pick ? pick.from : 'no website in the ads',
      places: [...new Set(places)].slice(0, 3).join('; '),
      mergedRows: row.mergedRows || 1,
      matchedBy: row.matchedBy || [],
      jobUrl: row.jobUrl || null,
    },
  };
});

// One entry per distinct website; at most maxWebsites go to the paid legal notice check.
const max = Math.max(1, Math.round(Number($('Settings').first().json.maxWebsites) || 10));
const websites = [...new Set($input.all().map(item => item.json.website).filter(Boolean))];
return [{ json: { websites: websites.slice(0, max), notChecked: websites.slice(max) } }];

// Stops here when the run did not succeed or the actor rejected its input, with Apify's own status message.
const run = $input.first().json;
const message = run.statusMessage || '';
if (run.status !== 'SUCCEEDED' || /^Rejected/i.test(message)) {
  throw new Error(`Run ${run.id} ended with status ${run.status}: ${message}`);
}
if (!run.defaultDatasetId) {
  throw new Error(`Run ${run.id} has no dataset.`);
}
return [{ json: { runId: run.id, datasetId: run.defaultDatasetId, statusMessage: message } }];

// One row per employer: the company row, the website it got and the data of that website's legal notice.
// nameCheck compares the employer with the name in the legal notice after removing legal forms and words such as
// "Niederlassung": an application link or an e-mail address can belong to a group company or a service provider.
const STRIP = /\b(gmbh|mbh|ag|se|kg|ohg|gbr|ug|ev|eg|kgaa|co|und|haftungsbeschraenkt|ltd|inc|llc|bv|nv|sa|sarl|niederlassung|zweigniederlassung|filiale|standort)\b/g;
function nameKey(text) {
  return String(text || '').toLowerCase()
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
    .replace(/[^a-z0-9]+/g, ' ').replace(STRIP, ' ').replace(/\s+/g, ' ').trim();
}
function sameName(a, b) {
  const x = nameKey(a);
  const y = nameKey(b);
  return Boolean(x && y) && (x === y || x.startsWith(y + ' ') || y.startsWith(x + ' '));
}

const companies = $('Pick a website per company').all().map(item => item.json);
const notChecked = new Set($('Collect websites').first().json.notChecked || []);
const legal = new Map();
for (const item of $input.all()) {
  const row = item.json;
  if (!row || !row.input || !row.status) continue;  // the IF node's false branch brings no legal notice rows
  for (const key of [row.input, ...(row.duplicateInputs || [])]) legal.set(String(key).toLowerCase(), row);
}
return companies.map(c => {
  const row = c.website ? legal.get(c.website) : null;
  let nameCheck = 'no website in the ads';
  if (c.website && notChecked.has(c.website)) nameCheck = 'not checked: maxWebsites reached';
  else if (c.website && !row) nameCheck = 'no row from the Imprint & VAT Check';
  else if (row && !row.companyName) nameCheck = `no company name in the legal notice (status ${row.status}, ${row.reason})`;
  else if (row) nameCheck = sameName(c.employer, row.companyName) ? 'legal notice names the employer'
    : 'legal notice names another company: check by hand';
  return {
    json: {
      employer: c.employer,
      website: c.website,
      websiteFrom: c.websiteFrom,
      nameCheck,
      legalName: row ? row.companyName ?? null : null,
      street: row ? row.street ?? null : null,
      postalCode: row ? row.postalCode ?? null : null,
      city: row ? row.city ?? null : null,
      country: row ? row.country ?? null : null,
      email: row ? row.email ?? null : null,
      phone: row ? row.phone ?? null : null,
      registerCourt: row ? row.registerCourt ?? null : null,
      registerNumber: row ? row.registerNumber ?? null : null,
      vatId: row ? row.vatId ?? null : null,
      vatStatus: row ? row.vatStatus ?? null : null,
      imprintStatus: row ? row.status : null,
      imprintReason: row ? row.reason ?? null : null,
      impressumUrl: row ? row.impressumUrl ?? null : null,
      places: c.places,
      mergedRows: c.mergedRows,
      matchedBy: c.matchedBy,
      jobUrl: c.jobUrl,
    },
  };
});
